SELECT CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(rating) AS total_rating, SUM(SUM(rating)) OVER (ORDER BY CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END) AS cumulative_rating FROM suppliers WHERE supplier_name NOT LIKE 'Gl%' GROUP BY CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket ASC
